cpp.setup:
auto* control = new fluent::collections::FlipView(%PARENT%);
const struct { QString badge; QString title; QString summary; } slides[] = {
    {QStringLiteral("Slide 1 of 3"), QStringLiteral("Sunrise"), QStringLiteral("Warm amber highlights and hero-banner contrast check.")},
    {QStringLiteral("Slide 2 of 3"), QStringLiteral("Ocean"), QStringLiteral("Balanced blue palette for calm workspace surfaces.")},
    {QStringLiteral("Slide 3 of 3"), QStringLiteral("Forest"), QStringLiteral("Natural green accents with high-legibility captions.")},
};
for (const auto& slide : slides) {
    auto* page = new fluent::layout::Card;
    auto* lay = new QVBoxLayout(page);
    lay->setContentsMargins(20, 16, 20, 16);
    lay->setSpacing(6);
    auto* badge = new fluent::textfields::Label(slide.badge, page);
    badge->setFluentTypography(Typography::FontRole::Caption);
    badge->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    lay->addWidget(badge);
    auto* heading = new fluent::textfields::Label(slide.title, page);
    heading->setFluentTypography(Typography::FontRole::Subtitle);
    lay->addWidget(heading);
    auto* summary = new fluent::textfields::Label(slide.summary, page);
    summary->setWordWrap(true);
    summary->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
    lay->addWidget(summary);
    lay->addStretch();
    control->addPage(page, fluent::WidgetOwnership::Owned);
}
control->setCurrentIndex(0);
